#!/usr/bin/env python3
"""CLI tool to scrape web pages and extract structured data.

Extracts JSON-LD, Open Graph, Twitter Cards, tables, and custom CSS selectors.
Outputs JSONL to stdout or a file.

Examples:
    python web_scraper.py https://example.com
    python web_scraper.py urls.txt -o results.jsonl
    python web_scraper.py https://example.com --extract title=h1,price=".price"
    python web_scraper.py https://example.com --tables --format csv
    echo "https://example.com" | python web_scraper.py -
"""

import asyncio
import csv
import io
import json
import sys
import time
from dataclasses import asdict, dataclass, field
from datetime import datetime, timezone
from pathlib import Path
from typing import Any

import click
import httpx
from bs4 import BeautifulSoup


# ---------------------------------------------------------------------------
# Data models
# ---------------------------------------------------------------------------

@dataclass
class PageData:
    url: str
    status: int | None = None
    title: str | None = None
    json_ld: list[dict] = field(default_factory=list)
    open_graph: dict[str, str] = field(default_factory=dict)
    twitter_card: dict[str, str] = field(default_factory=dict)
    meta: dict[str, str] = field(default_factory=dict)
    tables: list[list[list[str]]] = field(default_factory=list)
    links: list[str] = field(default_factory=list)
    custom: dict[str, Any] = field(default_factory=dict)
    error: str | None = None
    scraped_at: str = ""

    def __post_init__(self):
        if not self.scraped_at:
            self.scraped_at = datetime.now(timezone.utc).isoformat()


# ---------------------------------------------------------------------------
# Extraction helpers
# ---------------------------------------------------------------------------

def _extract_json_ld(soup: BeautifulSoup) -> list[dict]:
    results = []
    for tag in soup.find_all("script", type="application/ld+json"):
        try:
            data = json.loads(tag.string or "")
            if isinstance(data, list):
                results.extend(data)
            elif isinstance(data, dict):
                results.append(data)
        except (json.JSONDecodeError, TypeError):
            continue
    return results


def _extract_open_graph(soup: BeautifulSoup) -> dict[str, str]:
    og = {}
    for tag in soup.find_all("meta", property=lambda v: v and v.startswith("og:")):
        key = tag.get("property", "").removeprefix("og:")
        content = tag.get("content", "")
        if key and content:
            og[key] = content
    return og


def _extract_twitter_card(soup: BeautifulSoup) -> dict[str, str]:
    tc = {}
    for tag in soup.find_all("meta", attrs={"name": lambda v: v and v.startswith("twitter:")}):
        key = tag.get("name", "").removeprefix("twitter:")
        content = tag.get("content", "")
        if key and content:
            tc[key] = content
    return tc


def _extract_meta(soup: BeautifulSoup) -> dict[str, str]:
    meta = {}
    for tag in soup.find_all("meta"):
        name = tag.get("name") or tag.get("property", "")
        content = tag.get("content", "")
        if name and content and not name.startswith(("og:", "twitter:")):
            meta[name] = content
    return meta


def _extract_tables(soup: BeautifulSoup) -> list[list[list[str]]]:
    tables = []
    for table_tag in soup.find_all("table"):
        rows = []
        for tr in table_tag.find_all("tr"):
            cells = [
                cell.get_text(strip=True)
                for cell in tr.find_all(["td", "th"])
            ]
            if cells:
                rows.append(cells)
        if rows:
            tables.append(rows)
    return tables


def _extract_links(soup: BeautifulSoup) -> list[str]:
    return list(dict.fromkeys(
        a.get("href", "") for a in soup.find_all("a", href=True) if a["href"]
    ))


def _extract_custom(soup: BeautifulSoup, fields: dict[str, str]) -> dict[str, Any]:
    result = {}
    for key, selector in fields.items():
        elements = soup.select(selector)
        if not elements:
            result[key] = None
        elif len(elements) == 1:
            result[key] = elements[0].get_text(strip=True)
        else:
            result[key] = [el.get_text(strip=True) for el in elements]
    return result


def extract_all(html: str, url: str, *, fields: dict[str, str] | None = None) -> PageData:
    soup = BeautifulSoup(html, "lxml")
    title_tag = soup.find("title")

    page = PageData(
        url=url,
        title=title_tag.get_text(strip=True) if title_tag else None,
        json_ld=_extract_json_ld(soup),
        open_graph=_extract_open_graph(soup),
        twitter_card=_extract_twitter_card(soup),
        meta=_extract_meta(soup),
        tables=_extract_tables(soup),
        links=_extract_links(soup),
    )

    if fields:
        page.custom = _extract_custom(soup, fields)
    return page


# ---------------------------------------------------------------------------
# Fetching
# ---------------------------------------------------------------------------

async def fetch(
    client: httpx.AsyncClient,
    url: str,
    *,
    timeout: float,
    retries: int,
    sem: asyncio.Semaphore,
    fields: dict[str, str] | None = None,
) -> PageData:
    last_err = None
    async with sem:
        for attempt in range(retries):
            try:
                resp = await client.get(url, timeout=timeout, follow_redirects=True)
                if resp.status_code >= 400:
                    last_err = f"HTTP {resp.status_code}"
                    if resp.status_code < 500:
                        break
                    await asyncio.sleep(2 ** attempt)
                    continue

                page = extract_all(resp.text, url, fields=fields)
                page.status = resp.status_code
                return page

            except httpx.TimeoutException:
                last_err = "timeout"
            except httpx.RequestError as exc:
                last_err = str(exc)[:200]

            if attempt < retries - 1:
                await asyncio.sleep(2 ** attempt)

    page = PageData(url=url, error=last_err)
    return page


async def scrape(
    urls: list[str],
    *,
    concurrency: int,
    timeout: float,
    retries: int,
    delay: float,
    fields: dict[str, str] | None = None,
    user_agent: str | None = None,
) -> list[PageData]:
    sem = asyncio.Semaphore(concurrency)
    headers = {"User-Agent": user_agent or "Mozilla/5.0 (compatible; web-scraper-cli/1.0)"}

    async with httpx.AsyncClient(headers=headers) as client:
        async def _run(url: str) -> PageData:
            if delay > 0:
                await asyncio.sleep(delay)
            return await fetch(client, url, timeout=timeout, retries=retries, sem=sem, fields=fields)

        tasks = [asyncio.create_task(_run(u)) for u in urls]
        results = []
        for coro in asyncio.as_completed(tasks):
            results.append(await coro)
    return results


# ---------------------------------------------------------------------------
# Input / output helpers
# ---------------------------------------------------------------------------

def load_urls(path: str) -> list[str]:
    if path == "-":
        lines = sys.stdin.read().splitlines()
    else:
        lines = Path(path).read_text().splitlines()

    urls = []
    for line in lines:
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith("{"):
            try:
                obj = json.loads(line)
                if "url" in obj:
                    urls.append(obj["url"])
                    continue
            except json.JSONDecodeError:
                pass
        if line.startswith(("http://", "https://")):
            urls.append(line)
    return urls


def parse_fields(spec: str) -> dict[str, str]:
    result = {}
    for pair in spec.split(","):
        pair = pair.strip()
        if "=" in pair:
            key, sel = pair.split("=", 1)
            result[key.strip()] = sel.strip()
    return result


def tables_to_csv(tables: list[list[list[str]]]) -> str:
    buf = io.StringIO()
    writer = csv.writer(buf)
    for i, table in enumerate(tables):
        if i > 0:
            writer.writerow([])
        for row in table:
            writer.writerow(row)
    return buf.getvalue()


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

@click.command(context_settings={"help_option_names": ["-h", "--help"]})
@click.argument("input", metavar="INPUT")
@click.option("-o", "--output", type=click.Path(), help="Output file (default: stdout).")
@click.option("-c", "--concurrency", type=int, default=5, show_default=True, help="Max concurrent requests.")
@click.option("-t", "--timeout", type=float, default=15.0, show_default=True, help="Per-request timeout (seconds).")
@click.option("--retries", type=int, default=3, show_default=True, help="Max retries per URL on server errors.")
@click.option("--delay", type=float, default=0.0, show_default=True, help="Polite delay between requests (seconds).")
@click.option("--extract", "fields_spec", help="Custom fields: key=css_selector,key2=selector2")
@click.option("--tables", is_flag=True, help="Extract HTML tables.")
@click.option("--format", "fmt", type=click.Choice(["jsonl", "csv"]), default="jsonl", show_default=True, help="Output format.")
@click.option("--user-agent", help="Custom User-Agent header.")
@click.option("--compact", is_flag=True, help="Print compact JSON (no indentation).")
@click.option("-q", "--quiet", is_flag=True, help="Suppress progress output.")
def main(
    input: str,
    output: str | None,
    concurrency: int,
    timeout: float,
    retries: int,
    delay: float,
    fields_spec: str | None,
    tables: bool,
    fmt: str,
    user_agent: str | None,
    compact: bool,
    quiet: bool,
):
    """Scrape web pages and extract structured data.

    INPUT is a file with one URL per line, a single URL, or '-' for stdin.
    """
    # Treat bare URLs as a single-element input
    if input.startswith(("http://", "https://")):
        urls = [input]
    else:
        urls = load_urls(input)

    if not urls:
        click.echo("No URLs found in input.", err=True)
        raise SystemExit(1)

    fields = parse_fields(fields_spec) if fields_spec else None
    indent = None if compact else 2

    if not quiet:
        click.echo(f"Scraping {len(urls)} URL(s) with concurrency={concurrency}...", err=True)
        start = time.monotonic()

    results = asyncio.run(
        scrape(
            urls,
            concurrency=concurrency,
            timeout=timeout,
            retries=retries,
            delay=delay,
            fields=fields,
            user_agent=user_agent,
        )
    )

    if not quiet:
        elapsed = time.monotonic() - start
        errors = sum(1 for r in results if r.error)
        click.echo(f"Done: {len(results)} pages in {elapsed:.1f}s, {errors} error(s).", err=True)

    out_fh = open(output, "w", newline="") if output else sys.stdout

    try:
        if fmt == "csv" and tables:
            all_tables = []
            for page in results:
                all_tables.extend(page.tables)
            out_fh.write(tables_to_csv(all_tables))
        else:
            for page in results:
                d = asdict(page)
                # Drop tables from JSONL unless explicitly requested
                if not tables:
                    d.pop("tables", None)
                out_fh.write(json.dumps(d, ensure_ascii=False, indent=indent) + "\n")
    finally:
        if output:
            out_fh.close()

    raise SystemExit(1 if any(r.error for r in results) else 0)


if __name__ == "__main__":
    main()
